import { chmodSync, lstatSync, mkdirSync, mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterEach, describe, expect, it } from "vitest";
import { ensureEmbeddedPgTraversal } from "../embedded-runtime";

// Root-mode boot: embedded-postgres refuses to run as root, so it drops the
// cluster to a `postgres` user. That user must be able to *traverse* every
// ancestor of the paths it touches — the embedded binaries and the datadir — or
// the setuid spawn dies with EACCES before exec, and the dependency's spawn has
// no 'error' handler so the whole process crashes (the `/root` 0700 + npx-cache
// shape on `node:` images, and a root-owned `.lobu` under a 0077 umask). The
// helper grants traverse-only (`o+x`, never read/write) on exactly the missing
// components.
describe("ensureEmbeddedPgTraversal", () => {
	const dirs: string[] = [];
	afterEach(() => {
		while (dirs.length) rmSync(dirs.pop()!, { recursive: true, force: true });
	});

	function fixture(): string {
		const root = mkdtempSync(join(tmpdir(), "lobu-pgtrav-"));
		dirs.push(root);
		return root;
	}

	it("grants traverse on 0700 ancestors (the /root shape)", () => {
		const root = fixture();
		const home = join(root, "home");
		mkdirSync(home, { recursive: true });
		chmodSync(home, 0o700);
		const cache = join(home, "npx", "node_modules", "@lobu", "cli");
		mkdirSync(cache, { recursive: true });
		chmodSync(join(home, "npx"), 0o700);

		const granted = ensureEmbeddedPgTraversal([cache]);

		expect(granted).toContain(home);
		expect(granted).toContain(join(home, "npx"));
		expect(lstatSync(home).mode & 0o001).toBe(0o001);
		expect(lstatSync(join(home, "npx")).mode & 0o001).toBe(0o001);
		// An already-traversable component is left alone.
		expect(granted).not.toContain(cache);
	});

	it("is idempotent — a second run grants nothing new", () => {
		const root = fixture();
		const home = join(root, "home");
		mkdirSync(home, { recursive: true });
		chmodSync(home, 0o700);

		ensureEmbeddedPgTraversal([join(home, "npx")]);
		expect(lstatSync(home).mode & 0o001).toBe(0o001);

		expect(ensureEmbeddedPgTraversal([join(home, "npx")])).toEqual([]);
		expect(lstatSync(home).mode & 0o001).toBe(0o001);
	});

	it("no-ops when every component is already traversable", () => {
		const root = fixture();
		chmodSync(root, 0o755);
		expect(ensureEmbeddedPgTraversal([root])).toEqual([]);
	});

	it("creates a missing datadir ancestor and makes it traversable (cold boot)", () => {
		const root = fixture();
		const dataRoot = join(root, "home", ".lobu");
		// Reproduce the 0077 umask of a root container that created the parent.
		const previousUmask = process.umask(0o077);
		try {
			const granted = ensureEmbeddedPgTraversal([dataRoot]);
			expect(granted).toContain(dataRoot);
			expect(lstatSync(dataRoot).isDirectory()).toBe(true);
			expect(lstatSync(dataRoot).mode & 0o001).toBe(0o001);
		} finally {
			process.umask(previousUmask);
		}
	});
});
