#!/usr/bin/env node
/**
 * Bundle the single server entrypoint into a standalone ESM file consumed by
 * the published @lobu/cli package. One entry (server.ts) serves both backends.
 *
 * Why: prod runs under Node so isolated-vm (V8 native addon) loads. Running
 * the TS source through tsx exposes Node's CJS↔ESM lexer interop with
 * @lobu/core's CJS dist (#430 history). Bundling resolves all workspace
 * imports at build time, so Node only ever sees the bundle's own ESM
 * surface plus a small set of npm externals it can load from node_modules.
 *
 * Resolution conditions: 'bun' first, so workspace packages resolve to
 * their TS source (./src/index.ts via the package.json `bun` condition)
 * instead of their CJS dist. esbuild compiles the TS inline.
 *
 * External: bare specifiers stay external (loaded from node_modules at
 * runtime). Published `@lobu/cli` declares those runtime dependencies
 * directly so Node's resolver finds them from the CLI install. Native addons
 * (isolated-vm), embedded-postgres + pgvector binaries, and packages with
 * require-in-the-middle hooks (Sentry, OpenTelemetry, pino) MUST stay external
 * to keep their runtime hooks working.
 */

import esbuild from 'esbuild';
import { cpSync, existsSync, mkdirSync, rmSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const pkgDir = join(here, '..');

const commonOptions = {
  absWorkingDir: pkgDir,
  bundle: true,
  platform: 'node',
  target: 'node22',
  format: 'esm',
  conditions: ['bun', 'import', 'module', 'default'],
  // Bundle only @lobu/* workspace packages and relative imports. Everything
  // else stays external.
  plugins: [
    {
      name: 'external-non-workspace',
      setup(build) {
        build.onResolve({ filter: /.*/ }, (args) => {
          if (args.kind === 'entry-point') return null;
          const id = args.path;
          if (id.startsWith('.') || id.startsWith('/')) return null;
          // @lobu/pgvector-embedded ships prebuilt binary assets under
          // prebuilt/ that esbuild can't inline; keep it external so it loads
          // from node_modules with its assets intact (like the npm externals).
          if (id === '@lobu/pgvector-embedded' || id.startsWith('@lobu/pgvector-embedded/'))
            return { external: true };
          if (id.startsWith('@lobu/')) return null;
          return { external: true };
        });
      },
    },
  ],
  // CJS-style require() shim for any leftover require() calls in bundled
  // code (esbuild emits these when it inlines CJS-flavoured workspace src).
  // Don't inject __filename/__dirname here — esbuild emits per-module shims
  // when bundled CJS source references them; top-level shims would collide.
  banner: {
    js: `import { createRequire as __createRequire } from 'module'; const require = __createRequire(import.meta.url);`,
  },
  sourcemap: true,
  metafile: true,
  logLevel: 'info',
};

async function buildBundle(entryPoint, outfile) {
  const result = await esbuild.build({
    ...commonOptions,
    entryPoints: [entryPoint],
    outfile,
  });

  assertSingleConnectorWorkerIdentity(result.metafile, outfile);

  const output = Object.entries(result.metafile.outputs).find(([file]) =>
    file.endsWith(outfile),
  )?.[1];
  const bytes = output?.bytes ?? 0;
  console.log(
    `\n=== bundle ready: ${outfile} (${(bytes / 1024 / 1024).toFixed(2)} MB)`,
  );
  console.log(`    warnings: ${result.warnings.length}, errors: ${result.errors.length}`);
}

// Guard against the #v14 regression where a caller imported connector-worker
// via a cross-package `../../../connector-worker/src/...` path while the rest of
// the tree used its `@lobu/connector-worker/*` exports. The bundler then carried
// the same module twice — once as workspace `src`, once as compiled `dist` —
// treating equivalent code as separate modules. Fail the build if any
// connector-worker module stem is reached through both.
function assertSingleConnectorWorkerIdentity(metafile, outfile) {
  const byStem = new Map();
  for (const p of Object.keys(metafile.inputs)) {
    const m = p.match(/connector-worker\/(src|dist)\/(.+?)\.(?:m?[jt]s)$/);
    if (!m) continue;
    const [, kind, stem] = m;
    if (!byStem.has(stem)) byStem.set(stem, new Set());
    byStem.get(stem).add(kind);
  }
  const dupes = [...byStem.entries()]
    .filter(([, kinds]) => kinds.has('src') && kinds.has('dist'))
    .map(([stem]) => stem);
  console.log(
    `    connector-worker inputs: ${byStem.size} module stem(s), ${dupes.length} duplicated across src+dist`,
  );
  if (dupes.length > 0) {
    throw new Error(
      `[build-server-bundle] ${outfile}: ${dupes.length} connector-worker module(s) ` +
        `bundled through BOTH src and dist — import them via @lobu/connector-worker/* ` +
        `exports, not cross-package src paths:\n  ${dupes.sort().join('\n  ')}`,
    );
  }
}

// Single server graph for both backends: server.ts branches on DATABASE_URL
// (postgres:// = external; path/file:// = embedded, lazy-loading the embedded
// Postgres runtime so the external/prod path never resolves that binary).
//
// Two-file split for the Node-version gate:
//   server.bundle.mjs       — tiny gate entry (server-entry.ts). Zero app deps.
//                             Runs a dependency-free Node-major check, then
//                             dynamically imports ./server-main.bundle.mjs.
//   server-main.bundle.mjs  — the real server graph (server.ts + all deps).
//
// The gate MUST be its own file so esbuild can't hoist the server graph's
// @sentry/node → undici import above the check. On Node 18, undici references
// the absent `File` global and throws `File is not defined` at load —
// before any in-graph guard could run. Keeping the graph behind a runtime
// dynamic import to a *separate* bundle means undici only loads after the gate
// passes. server-entry.ts constructs the sibling URL at runtime so esbuild
// cannot resolve and inline it.
await buildBundle('src/server.ts', 'dist/server-main.bundle.mjs');
await buildBundle('src/server-entry.ts', 'dist/server.bundle.mjs');

const connectorsSrc = join(pkgDir, '..', 'connectors', 'src');
const connectorsDest = join(pkgDir, 'dist', 'connectors');
if (existsSync(connectorsSrc)) {
  if (existsSync(connectorsDest)) {
    rmSync(connectorsDest, { recursive: true, force: true });
  }
  mkdirSync(dirname(connectorsDest), { recursive: true });
  cpSync(connectorsSrc, connectorsDest, { recursive: true });
  console.log(`\n=== copied connectors: ${connectorsDest}`);
}
const fs = require("node:fs");
const path = require("node:path");

function copyDirIfExists(src, dest, filter) {
  if (!fs.existsSync(src)) return;
  if (fs.existsSync(dest)) {
    fs.rmSync(dest, { recursive: true, force: true });
  }
  fs.mkdirSync(path.dirname(dest), { recursive: true });
  fs.cpSync(src, dest, { recursive: true, filter });
}

// Skip internal test material (a __tests__ dir, or a *.test.* / *.spec.* file).
// cpSync skips a directory's entire subtree when the filter returns false.
function excludeTests(srcPath) {
  const segments = srcPath.split(path.sep);
  if (segments.includes("__tests__")) return false;
  return !/\.(test|spec)\.[cm]?[jt]sx?$/.test(path.basename(srcPath));
}

// Copy templates
copyDirIfExists("src/templates", "dist/templates");

// Copy the single bundled Lobu starter skill (includes memory guidance).
copyDirIfExists("../../skills/lobu", "dist/bundled-skills/lobu");

// Copy mcp-servers.json
const jsonSrc = "src/mcp-servers.json";
const jsonDest = "dist/mcp-servers.json";
if (fs.existsSync(jsonSrc)) {
  fs.cpSync(jsonSrc, jsonDest);
}

// Copy providers.json from monorepo config
const providersSrc = "../../config/providers.json";
const providersDest = "dist/providers.json";
if (fs.existsSync(providersSrc)) {
  fs.cpSync(providersSrc, providersDest);
}

// Copy bundled connector source files next to the embedded server bundle.
// The server lists these runtime code-based connectors for picker UIs and
// compiles them on demand when a workspace installs or runs one. Only the
// runtime connector source/manifests ship — internal tests are filtered out.
copyDirIfExists("../connectors/src", "dist/connectors", excludeTests);

// Vendor unified catalog manifests (`dist/catalogs/*.json`) for `lobu run`.
// Runtime resolves them via LOBU_CATALOG_URIS (default dist/catalogs/). CI
// builds the server first; if absent (local CLI build without build:server)
// the runtime falls back to on-demand compilation — no regression.
copyDirIfExists("../server/dist/catalogs", "dist/catalogs");

// Copy database migrations for the bundled embedded-Postgres local server.
copyDirIfExists("../../db/migrations", "dist/db/migrations");

// Copy the built owletto web UI (admin/console SPA) next to the server bundle
// so `lobu run` serves it — OAuth, MCP-client setup, and connection CRUD have
// no surface without it. owletto is a private submodule (`private: true`);
// only its compiled `dist/` ships in the CLI tarball, never the source. CI's
// publish flow builds it (`bun run build` in packages/owletto, gated on the
// submodule being present) before this script runs. Missing locally (fork or
// uninitialised submodule) → the copy is skipped and `lobu run` boots headless
// (API only), matching prior behaviour. `dev.ts` points WEB_DIST_DIR here.
copyDirIfExists("../owletto/dist", "dist/owletto/dist");

// Copy server bundles so `lobu run` is self-contained.
// @lobu/server is private (`private: true` in its package.json),
// so `npx @lobu/cli` users can never resolve it via npm — they only get
// what ships inside the CLI tarball. CI's publish flow builds the bundles
// (`build:server`) before this script runs; if they're missing locally, run
// `bun run --filter '@lobu/server' build:server` first.
// server.bundle.mjs is the tiny Node-version gate; it dynamically imports its
// sibling server-main.bundle.mjs (the real server graph) at runtime — so both
// must ship together. Missing server-main.bundle.mjs
// would make `lobu run` fail with a module-not-found after the gate passes.
for (const bundleName of ["server.bundle.mjs", "server-main.bundle.mjs"]) {
  const bundleSrc = `../server/dist/${bundleName}`;
  const bundleDest = `dist/${bundleName}`;
  if (fs.existsSync(bundleSrc)) {
    fs.cpSync(bundleSrc, bundleDest);
  } else {
    console.warn(
      `[cli build] server bundle missing at ${bundleSrc}; ` +
        "`lobu run` requires both server bundles. Run " +
        "`bun run --filter '@lobu/server' build:server` to bundle it."
    );
  }
}

// Vendor @lobu/pgvector-embedded into the CLI tarball. It's `private` (never
// published) but the bundled server needs it at runtime for embedded Postgres
// + pgvector. esbuild can't inline its prebuilt native binaries, so we ship
// the package's dist + prebuilt under dist/vendor/ (NOT node_modules, which
// npm strips from tarballs). embedded-runtime.ts loads this copy by path when
// the bare specifier isn't resolvable (i.e. in the published CLI). The `bun`
// export condition is stripped so a bun runtime resolves dist/index.js rather
// than the src/ that doesn't ship.
const pgvSrc = "../pgvector-embedded";
const pgvDest = "dist/vendor/pgvector-embedded";
function vendorPgvector() {
  if (
    !fs.existsSync(`${pgvSrc}/dist`) ||
    !fs.existsSync(`${pgvSrc}/prebuilt`)
  ) {
    return false;
  }
  copyDirIfExists(`${pgvSrc}/dist`, `${pgvDest}/dist`);
  copyDirIfExists(`${pgvSrc}/prebuilt`, `${pgvDest}/prebuilt`);
  const pgvPkg = JSON.parse(fs.readFileSync(`${pgvSrc}/package.json`, "utf8"));
  if (pgvPkg.exports?.["."]?.bun) {
    delete pgvPkg.exports["."].bun;
  }
  fs.mkdirSync(pgvDest, { recursive: true });
  fs.writeFileSync(
    `${pgvDest}/package.json`,
    `${JSON.stringify(pgvPkg, null, 2)}\n`
